#!/usr/bin/env bash
# Prints the Homebrew formula for a release.
# Usage: homebrew-formula.sh VERSION MACOS_SHA256
set -euo pipefail

version="$1"
macos_sha="$2"
base="https://github.com/vangheem/macpack/releases/download/v${version}"

cat <<EOF
# Generated by vangheem/macpack's release workflow; edits here are overwritten.
class Macpack < Formula
  desc "Move your Mac setup to a new Mac over an encrypted local connection"
  homepage "https://github.com/vangheem/macpack"
  url "${base}/macpack-macos-universal.tar.gz"
  sha256 "${macos_sha}"
  version "${version}"
  license "MIT"

  depends_on :macos
  depends_on "mas"

  def install
    bin.install "macpack"
  end

  def caveats
    <<~EOS
      Run macpack on both Macs; they find each other on the local network.

      Add macpack to ~/Applications (Spotlight, Launchpad, Dock) with:
        macpack install-app
      macpack also offers to do this the first time you run it.
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/macpack --version")
  end
end
EOF
